diff -ruN '--exclude=node_modules' '--exclude=.git' a/csv-stream.test.ts b/csv-stream.test.ts
--- a/csv-stream.test.ts	1970-01-01 00:00:00.000000000 +0000
+++ b/csv-stream.test.ts	2026-10-30 17:18:26.365179432 +0000
@@ -0,0 +1,145 @@
+import { expect, test } from "bun:test";
+import { CsvStream, parseCsv } from "./csv";
+
+type Outcome = { rows: string[][] } | { error: string };
+
+function whole(text: string): Outcome {
+  try {
+    return { rows: parseCsv(text) };
+  } catch (e) {
+    if (!(e instanceof SyntaxError)) throw e;
+    return { error: e.message };
+  }
+}
+
+function streamed(chunks: string[]): Outcome {
+  const s = new CsvStream();
+  const rows: string[][] = [];
+  try {
+    for (const c of chunks) rows.push(...s.push(c));
+    rows.push(...s.end());
+    return { rows };
+  } catch (e) {
+    if (!(e instanceof SyntaxError)) throw e;
+    return { error: e.message };
+  }
+}
+
+function* splits(text: string): Generator<string[]> {
+  // every way to cut the text into pieces, including empty pieces at the ends
+  const n = text.length;
+  for (let mask = 0; mask < 1 << Math.max(n - 1, 0); mask++) {
+    const parts: string[] = [];
+    let start = 0;
+    for (let k = 1; k < n; k++) {
+      if (mask & (1 << (k - 1))) {
+        parts.push(text.slice(start, k));
+        start = k;
+      }
+    }
+    parts.push(text.slice(start));
+    yield parts;
+  }
+  yield ["", ...text.split(""), ""];
+}
+
+const cases = [
+  "",
+  "\n",
+  "\r\n",
+  "\r",
+  "a\r",
+  "a\rb\r\n",
+  "a\r\r\n",
+  "\uFEFF",
+  "\uFEFFa,b",
+  "\uFEFF\uFEFF",
+  "a\uFEFF",
+  "a,",
+  ",\n,",
+  "a\n\nb\n",
+  '"a""b",c\r\n',
+  '"a\r\nb"\r\n',
+  '""',
+  '""""',
+  '"a"\r',
+  '"a"\rb',
+  '"a"\r\r\n',
+  '"a"b',
+  '"a"""',
+  '"a',
+  '"a""',
+  'a"b',
+  'a,"b',
+  '"\uFEFF",x',
+];
+
+test("every split of each case gives what parseCsv gives, rows or SyntaxError", () => {
+  for (const text of cases) {
+    const expected = whole(text);
+    for (const chunks of splits(text)) expect({ text, chunks, out: streamed(chunks) }).toEqual({ text, chunks, out: expected });
+  }
+});
+
+test("random inputs split at random agree with parseCsv", () => {
+  let seed = 12345;
+  const rand = (n: number) => {
+    seed = (seed * 1103515245 + 12345) & 0x7fffffff;
+    return seed % n;
+  };
+  const alphabet = ['"', ",", "\r", "\n", "a", "b", "\uFEFF"];
+  for (let t = 0; t < 3000; t++) {
+    let text = "";
+    const len = rand(16);
+    for (let k = 0; k < len; k++) text += alphabet[rand(alphabet.length)];
+    const chunks: string[] = [];
+    let at = 0;
+    while (at < text.length) {
+      const size = rand(4);
+      chunks.push(text.slice(at, at + size));
+      at += size;
+    }
+    expect({ text, out: streamed(chunks) }).toEqual({ text, out: whole(text) });
+  }
+});
+
+test("a row is returned as soon as its row end arrives", () => {
+  const s = new CsvStream();
+  expect(s.push('"a"')).toEqual([]);
+  expect(s.push("\r")).toEqual([]);
+  expect(s.push("\nb\r")).toEqual([["a"]]);
+  expect(s.push("\n")).toEqual([["b"]]);
+  expect(s.end()).toEqual([]);
+});
+
+test("the BOM is dropped only at the very start of the input, even after empty chunks", () => {
+  const s = new CsvStream();
+  expect(s.push("")).toEqual([]);
+  expect(s.push("\uFEFFa\n")).toEqual([["a"]]);
+  expect(s.push("\uFEFFb\n")).toEqual([["\uFEFFb"]]);
+});
+
+test("after an error or end, every call throws", () => {
+  const s = new CsvStream();
+  expect(() => s.push('"a"x')).toThrow(SyntaxError);
+  expect(() => s.push("b")).toThrow(SyntaxError);
+  expect(() => s.end()).toThrow(SyntaxError);
+  const t = new CsvStream();
+  t.end();
+  expect(() => t.push("a")).toThrow();
+  expect(() => t.end()).toThrow();
+});
+
+test("many small chunks take time linear in the input", () => {
+  const s = new CsvStream();
+  let rows = 0;
+  const line = 'abc,"d""e\nf",g\r\n';
+  for (let k = 0; k < 200_000; k++) for (const c of line) rows += s.push(c).length;
+  // one long quoted field spread over many chunks
+  s.push('"');
+  for (let k = 0; k < 200_000; k++) s.push("xy");
+  s.push('"');
+  const last = s.end();
+  expect(rows).toBe(200_000);
+  expect(last[0]![0]!.length).toBe(400_000);
+});
diff -ruN '--exclude=node_modules' '--exclude=.git' a/csv.ts b/csv.ts
--- a/csv.ts	2026-10-30 17:17:21.985480549 +0000
+++ b/csv.ts	2026-10-30 17:18:09.961237218 +0000
@@ -50,3 +50,166 @@
   rows.push(row);
   return rows;
 }
+
+const enum State {
+  RowStart, // nothing of the current row has arrived yet
+  FieldStart, // just after a `,`
+  Unquoted,
+  UnquotedCr, // an unquoted field followed by a `\r` that may start a `\r\n`
+  Quoted,
+  QuotedQuote, // a `"` inside a quoted field that may be the first of a `""`
+  AfterQuote,
+  AfterQuoteCr, // a `\r` after a closing quote that must be followed by `\n`
+}
+
+/**
+ * Parses CSV as `parseCsv` does, from chunks split anywhere. `push` returns the rows whose row end has arrived and
+ * `end` the rest; together they equal `parseCsv` of the whole input, and an input it rejects makes `push` or `end`
+ * throw its SyntaxError. The work for a chunk depends only on that chunk and the rows it completes. After an error
+ * or `end`, every call throws.
+ */
+export class CsvStream {
+  private state = State.RowStart;
+  private row: string[] = [];
+  private field = "";
+  private offset = 0; // offset in the whole input of the next character to arrive
+  private crOffset = 0;
+  private started = false;
+  private ended = false;
+  private error: unknown = undefined;
+
+  push(chunk: string): string[][] {
+    this.check();
+    try {
+      return this.feed(chunk);
+    } catch (e) {
+      this.error = e;
+      throw e;
+    }
+  }
+
+  end(): string[][] {
+    this.check();
+    this.ended = true;
+    const rows: string[][] = [];
+    switch (this.state) {
+      case State.RowStart:
+        return rows;
+      case State.Quoted:
+        this.error = new SyntaxError("a quoted field is still open at the end of the input");
+        throw this.error;
+      case State.AfterQuoteCr:
+        this.error = new SyntaxError(`unexpected "\\r" after a closing quote at offset ${this.crOffset}`);
+        throw this.error;
+      case State.UnquotedCr:
+        this.field += "\r";
+        break;
+    }
+    this.row.push(this.field);
+    rows.push(this.row);
+    this.row = [];
+    this.field = "";
+    return rows;
+  }
+
+  private check(): void {
+    if (this.error !== undefined) throw this.error;
+    if (this.ended) throw new Error("the stream has already ended");
+  }
+
+  private feed(chunk: string): string[][] {
+    const rows: string[][] = [];
+    let i = 0;
+    if (!this.started && chunk.length > 0) {
+      this.started = true;
+      if (chunk[0] === "﻿") i = 1;
+    }
+    const base = this.offset;
+    this.offset += chunk.length;
+    const endRow = () => {
+      this.row.push(this.field);
+      rows.push(this.row);
+      this.row = [];
+      this.field = "";
+      this.state = State.RowStart;
+    };
+    while (i < chunk.length) {
+      const c = chunk[i]!;
+      switch (this.state) {
+        case State.RowStart:
+        case State.FieldStart:
+          if (c === '"') {
+            this.state = State.Quoted;
+            i++;
+          } else this.state = State.Unquoted;
+          break;
+        case State.Unquoted: {
+          let j = i;
+          while (j < chunk.length) {
+            const d = chunk[j];
+            if (d === "," || d === "\r" || d === "\n" || d === '"') break;
+            j++;
+          }
+          this.field += chunk.slice(i, j);
+          i = j;
+          if (i === chunk.length) break;
+          const d = chunk[i++];
+          if (d === ",") {
+            this.row.push(this.field);
+            this.field = "";
+            this.state = State.FieldStart;
+          } else if (d === "\n") endRow();
+          else if (d === "\r") this.state = State.UnquotedCr;
+          else throw new SyntaxError(`a quote in a field that is not quoted, at offset ${base + i - 1}`);
+          break;
+        }
+        case State.UnquotedCr:
+          if (c === "\n") {
+            i++;
+            endRow();
+          } else {
+            this.field += "\r";
+            this.state = State.Unquoted;
+          }
+          break;
+        case State.Quoted: {
+          const j = chunk.indexOf('"', i);
+          if (j < 0) {
+            this.field += chunk.slice(i);
+            i = chunk.length;
+          } else {
+            this.field += chunk.slice(i, j);
+            i = j + 1;
+            this.state = State.QuotedQuote;
+          }
+          break;
+        }
+        case State.QuotedQuote:
+          if (c === '"') {
+            this.field += '"';
+            i++;
+            this.state = State.Quoted;
+          } else this.state = State.AfterQuote;
+          break;
+        case State.AfterQuote:
+          i++;
+          if (c === ",") {
+            this.row.push(this.field);
+            this.field = "";
+            this.state = State.FieldStart;
+          } else if (c === "\n") endRow();
+          else if (c === "\r") {
+            this.crOffset = base + i - 1;
+            this.state = State.AfterQuoteCr;
+          } else throw new SyntaxError(`unexpected ${JSON.stringify(c)} after a closing quote at offset ${base + i - 1}`);
+          break;
+        case State.AfterQuoteCr:
+          if (c !== "\n") throw new SyntaxError(`unexpected "\\r" after a closing quote at offset ${this.crOffset}`);
+          i++;
+          endRow();
+          break;
+      }
+    }
+    return rows;
+  }
+}

diff -ruN '--exclude=node_modules' '--exclude=.git' a/deny.edge.test.ts b/deny.edge.test.ts
--- a/deny.edge.test.ts	1970-01-01 00:00:00.000000000 +0000
+++ b/deny.edge.test.ts	2026-10-30 17:18:26.157745812 +0000
@@ -0,0 +1,42 @@
+import { expect, test } from 'bun:test';
+import { homedir } from 'node:os';
+import { denyListed } from './deny.ts';
+
+const cwd = '/work/repo';
+const hit = (argv: string[]) => denyListed(argv, cwd)?.name;
+
+test('git long options with =value and abbreviations', () => {
+  expect(hit(['git', 'push', '--force=yes'])).toBe('force-push');
+  expect(hit(['git', 'push', '--mir'])).toBe('force-push');
+  expect(hit(['git', 'reset', '--ha'])).toBe('reset-hard');
+  expect(hit(['git', 'clean', '--for'])).toBe('clean-force');
+  expect(hit(['git', '--git-dir=.git', 'push', '-f'])).toBe('force-push');
+  expect(hit(['git', '--work-tree', 'w', '--namespace', 'n', 'reset', '--hard'])).toBe('reset-hard');
+  expect(hit(['git', 'push', '--'])).toBeUndefined();
+  expect(hit(['git', 'push', 'origin', '--', '+main'])).toBe('force-push');
+  expect(hit(['git', 'push', 'origin', '--', '-f'])).toBeUndefined();
+  expect(hit(['git', 'reset', '--', '--hard'])).toBeUndefined();
+  expect(hit(['git'])).toBeUndefined();
+  expect(hit(['git', '-C'])).toBeUndefined();
+});
+
+test('rm targets that resolve to cwd, home or nothing', () => {
+  expect(hit(['rm', '-rf', ''])).toBe('rm-outside');
+  expect(hit(['rm', '-rf', './'])).toBe('rm-outside');
+  expect(hit(['rm', '-rf', 'src/..'])).toBe('rm-outside');
+  expect(hit(['rm', '-rf', '*/../..'])).toBe('rm-outside');
+  expect(hit(['rm', '-rf', '../*'])).toBe('rm-outside');
+  expect(hit(['rm', '-rf', '~/x'])).toBe(`${homedir()}/x`.startsWith(cwd + '/') ? undefined : 'rm-outside');
+  expect(hit(['rm', '-rf', '`pwd`'])).toBe('rm-outside');
+  expect(hit(['rm', '-rf', '--'])).toBe('rm-outside');
+  expect(hit(['rm', '--rec', '/etc'])).toBe('rm-outside');
+  expect(hit(['rm', '-r', 'a', '-v', '/etc'])).toBe('rm-outside');
+});
+
+test('find start paths after leading options', () => {
+  expect(hit(['find', '-L', '/', '-delete'])).toBe('rm-outside');
+  expect(hit(['find', '-D', 'tree', '/', '-delete'])).toBe('rm-outside');
+  expect(hit(['find', '-L', '-delete'])).toBeUndefined();
+  expect(hit(['find', '~bob', '-exec', 'rm', '{}', ';'])).toBe('rm-outside');
+  expect(hit(['find', '/work/repo', '-delete'])).toBeUndefined();
+});
diff -ruN '--exclude=node_modules' '--exclude=.git' a/deny.ts b/deny.ts
--- a/deny.ts	2026-10-30 17:17:21.994982213 +0000
+++ b/deny.ts	2026-10-30 17:18:14.953625690 +0000
@@ -1,5 +1,5 @@
 import { homedir } from 'node:os';
-import { isAbsolute, relative, resolve } from 'node:path';
+import { basename, isAbsolute, relative, resolve } from 'node:path';

 export type Hit = { name: 'force-push' | 'reset-hard' | 'clean-force' | 'rm-outside'; reason: string };

@@ -36,5 +36,87 @@
 //
 // Anything else: undefined.
 export function denyListed(argv: string[], cwd: string): Hit | undefined {
-  throw new Error('not implemented');
+  if (argv.length === 0) return undefined;
+  const cmd = basename(argv[0]);
+  if (cmd === 'git') return gitHit(argv.slice(1));
+  if (cmd === 'rm') return rmHit(argv.slice(1), cwd);
+  if (cmd === 'find') return findHit(argv.slice(1), cwd);
+  return undefined;
+}
+
+const outside = (reason: string): Hit => ({ name: 'rm-outside', reason });
+
+// A long option `word` (with or without =value) naming one of `names`, including the unambiguous
+// prefixes git and getopt accept (--forc, --mir).
+function longOpt(word: string, names: string[]): boolean {
+  if (!word.startsWith('--') || word === '--') return false;
+  const name = word.slice(2).split('=')[0];
+  return name !== '' && names.some((n) => n.startsWith(name));
+}
+
+const shortGroup = (word: string, letters: string) =>
+  word.startsWith('-') && !word.startsWith('--') && [...word.slice(1)].some((c) => letters.includes(c));
+
+const GIT_VALUE_OPTS = ['-C', '-c', '--git-dir', '--work-tree', '--namespace'];
+
+function gitHit(args: string[]): Hit | undefined {
+  let i = 0;
+  while (i < args.length && args[i].startsWith('-')) i += GIT_VALUE_OPTS.includes(args[i]) ? 2 : 1;
+  const sub = args[i];
+  const rest = args.slice(i + 1);
+  const dashDash = rest.indexOf('--');
+  const opts = dashDash === -1 ? rest : rest.slice(0, dashDash);
+  if (sub === 'push') {
+    for (const [k, w] of rest.entries()) {
+      const isOpt = (dashDash === -1 || k < dashDash) && w.startsWith('-');
+      if (isOpt && (longOpt(w, ['force', 'force-with-lease', 'mirror', 'delete', 'prune']) || shortGroup(w, 'fd')))
+        return { name: 'force-push', reason: `git push ${w} rewrites or deletes remote history` };
+      if (!isOpt && (w.startsWith('+') || w.startsWith(':')))
+        return { name: 'force-push', reason: `git push refspec ${w} forces or deletes a remote ref` };
+    }
+  }
+  if (sub === 'reset' && opts.some((w) => longOpt(w, ['hard'])))
+    return { name: 'reset-hard', reason: 'git reset --hard discards uncommitted work' };
+  if (sub === 'clean' && opts.some((w) => longOpt(w, ['force']) || shortGroup(w, 'f')) && !rest.some((w) => w === '-n' || w === '--dry-run'))
+    return { name: 'clean-force', reason: 'git clean --force deletes untracked files' };
+  return undefined;
+}
+
+// Why `path` may not be touched, or undefined when it is inside cwd (cwd itself only when allowSame).
+function badPath(path: string, cwd: string, allowSame: boolean): string | undefined {
+  if (path.includes('$') || path.includes('`') || (path.startsWith('~') && path !== '~' && !path.startsWith('~/')))
+    return `${path} cannot be resolved before it runs`;
+  if (!insideWorkspace(path, cwd)) return `${path} is outside the working directory`;
+  if (!allowSame && sameDir(path, cwd)) return `${path} is the working directory itself`;
+  return undefined;
+}
+
+function rmHit(args: string[], cwd: string): Hit | undefined {
+  const dashDash = args.indexOf('--');
+  const flags = (dashDash === -1 ? args : args.slice(0, dashDash)).filter((w) => w.startsWith('-'));
+  const targets = [
+    ...(dashDash === -1 ? args : args.slice(0, dashDash)).filter((w) => !w.startsWith('-')),
+    ...(dashDash === -1 ? [] : args.slice(dashDash + 1)),
+  ];
+  if (!flags.some((w) => longOpt(w, ['recursive']) || shortGroup(w, 'rR'))) return undefined;
+  if (targets.length === 0) return outside('rm -r without targets (they may come from xargs)');
+  for (const t of targets) {
+    const why = badPath(t, cwd, false);
+    if (why) return outside(`rm -r: ${why}`);
+  }
+  return undefined;
+}
+
+function findHit(args: string[], cwd: string): Hit | undefined {
+  if (!args.some((w) => w === '-delete' || w === '-exec' || w === '-execdir')) return undefined;
+  let i = 0;
+  // Leading options that come before the start paths: -H, -L, -P, -O<level>, -D <debugopts>.
+  while (i < args.length && /^-([HLP]+|O\d*|D)$/.test(args[i])) i += args[i] === '-D' ? 2 : 1;
+  const end = args.findIndex((w, k) => k >= i && w.startsWith('-'));
+  const starts = args.slice(i, end === -1 ? args.length : end);
+  for (const p of starts.length ? starts : ['.']) {
+    const why = badPath(p, cwd, true);
+    if (why) return outside(`find deleting or executing: ${why}`);
+  }
+  return undefined;
 }

diff -ruN '--exclude=node_modules' '--exclude=.git' a/edit.edge.test.ts b/edit.edge.test.ts
--- a/edit.edge.test.ts	1970-01-01 00:00:00.000000000 +0000
+++ b/edit.edge.test.ts	2026-10-30 17:19:30.637749645 +0000
@@ -0,0 +1,34 @@
+import { expect, test } from 'bun:test';
+import { applyEdit } from './edit.ts';
+
+test('deleting the last line of a file without a trailing newline', () => {
+  expect(applyEdit('a\nb  ', { old_text: 'b\n', new_text: '' })).toEqual({
+    content: 'a',
+    applied: { from: 2, to: 2, tier: 'trailing-space', count: 1 },
+  });
+});
+
+test('indentation tier swaps tabs in old_text for the file indentation', () => {
+  expect(applyEdit('x\n  b\n', { old_text: '\tb', new_text: '\tc\n\td' })).toEqual({
+    content: 'x\n  c\n  d\n',
+    applied: { from: 2, to: 2, tier: 'indentation', count: 1 },
+  });
+});
+
+test('replace_all with no exact match still reports not found', () => {
+  const r = applyEdit('a\nb\na\n', { old_text: 'q', new_text: 'z', replace_all: true });
+  expect('error' in r && r.error).toContain('not found');
+});
+
+test('first-line pointer lists at most 5 lines', () => {
+  const r = applyEdit('a b\n'.repeat(6), { old_text: 'a b\nzz', new_text: 'z' });
+  expect('error' in r && r.error).toContain('first line appears at line 1, 2, 3, 4, 5');
+  expect('error' in r && r.error).not.toContain('5, 6');
+});
+
+test('replace_all reports the span from the first to the last match', () => {
+  expect(applyEdit('x\ny\nx\n', { old_text: 'x', new_text: 'z', replace_all: true })).toEqual({
+    content: 'z\ny\nz\n',
+    applied: { from: 1, to: 3, tier: 'exact', count: 2 },
+  });
+});
diff -ruN '--exclude=node_modules' '--exclude=.git' a/edit.ts b/edit.ts
